import{_ as t,o as a,a as s,a2 as o}from"./chunks/framework.DCcmcJcL.js";const g=JSON.parse('{"title":"Architecture Overview","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/overview.md","filePath":"architecture/overview.md","lastUpdated":1789464754000}'),d={name:"architecture/overview.md"};function n(r,e,i,c,p,l){return a(),s("div",null,e[0]||(e[0]=[o(`<h1 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h1><p>Bagisto is a Laravel application whose features live in 42 packages under <code>packages/Webkul/</code>, inside a thin application shell that registers them, holds the configuration and serves the built assets. This page maps the project so you know where to look. <a href="./backend.html">Backend Architecture</a> and <a href="./frontend.html">Frontend Architecture</a> go one level deeper.</p><h2 id="technology-stack" tabindex="-1">Technology Stack <a class="header-anchor" href="#technology-stack" aria-label="Permalink to &quot;Technology Stack&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Bagisto 2.5</th></tr></thead><tbody><tr><td>PHP</td><td>8.4</td></tr><tr><td>Framework</td><td>Laravel 13</td></tr><tr><td>Modules and models</td><td><code>konekt/concord</code> 1.18</td></tr><tr><td>Data access</td><td><code>prettus/l5-repository</code> 4, through <code>Webkul\\Core\\Eloquent\\Repository</code></td></tr><tr><td>Front end</td><td>Vue.js 3.5, Tailwind CSS 4, Vite 6</td></tr><tr><td>Tests</td><td>Pest 5 and Playwright</td></tr><tr><td>Databases</td><td>MySQL 8.0, MariaDB 10.11, PostgreSQL 16</td></tr></tbody></table><p>Bagisto 2.4 runs on PHP 8.3 or 8.4 with Laravel 12, Tailwind CSS 3 and Pest 3, and supports MySQL and MariaDB only. <a href="./../advanced/database-compatibility.html">Database Compatibility</a> explains the <code>db_grammar()</code> helper that keeps package code portable across the three databases.</p><p>Both the admin (the <code>Admin</code> package) and the storefront (the <code>Shop</code> package, skinned by <a href="./../theme-development/getting-started.html">themes</a>) are Blade pages with Vue components mounted inside them. There is no separate single-page application to build.</p><h2 id="project-structure" tabindex="-1">Project Structure <a class="header-anchor" href="#project-structure" aria-label="Permalink to &quot;Project Structure&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my-bagisto-store/</span></span>
<span class="line"><span>├── app/                    # Thin shell: AppServiceProvider and the EncryptCookies middleware</span></span>
<span class="line"><span>├── bootstrap/</span></span>
<span class="line"><span>│   ├── app.php             # Global middleware, CSRF exclusions, trusted proxies, the /up health route</span></span>
<span class="line"><span>│   └── providers.php       # Every service provider, including one for each Bagisto package</span></span>
<span class="line"><span>├── config/</span></span>
<span class="line"><span>│   ├── concord.php         # Concord modules: the packages that register models</span></span>
<span class="line"><span>│   ├── themes.php          # Storefront and admin themes, their view paths and Vite builds</span></span>
<span class="line"><span>│   ├── bagisto-vite.php    # Vite builds looked up by namespace: admin, shop, installer</span></span>
<span class="line"><span>│   └── ...                 # Laravel&#39;s config files, plus elasticsearch, images, imagecache, purify, responsecache</span></span>
<span class="line"><span>├── database/               # Laravel&#39;s own tables; DatabaseSeeder calls the Installer package&#39;s seeder</span></span>
<span class="line"><span>├── lang/                   # Laravel&#39;s translations (auth, pagination, passwords, validation) in 22 locales</span></span>
<span class="line"><span>├── packages/Webkul/        # The 42 Bagisto packages</span></span>
<span class="line"><span>├── public/</span></span>
<span class="line"><span>│   ├── index.php</span></span>
<span class="line"><span>│   └── themes/             # Built Vite bundles for admin, shop and installer</span></span>
<span class="line"><span>├── resources/</span></span>
<span class="line"><span>│   ├── themes/             # Views of storefront themes you publish or create</span></span>
<span class="line"><span>│   └── ...                 # Laravel skeleton css and js, built only by the root vite.config.js</span></span>
<span class="line"><span>├── routes/                 # web.php is empty; console.php holds Laravel&#39;s inspire command</span></span>
<span class="line"><span>├── storage/                # Logs, caches, uploads in app/public, and the installed marker</span></span>
<span class="line"><span>├── tests/                  # Pest.php, shared datasets and cross-package unit tests</span></span>
<span class="line"><span>├── composer.json           # Maps each Webkul\\&lt;Name&gt;\\ namespace to packages/Webkul/&lt;Name&gt;/src</span></span>
<span class="line"><span>├── phpunit.xml             # One test suite for each package that has tests</span></span>
<span class="line"><span>└── vite.config.js          # Laravel skeleton build; Bagisto&#39;s pages don&#39;t use it</span></span></code></pre></div><p>Routes, migrations, views and translations all come from the packages, which is why <code>routes/</code>, <code>database/</code> and <code>resources/</code> in the application root hold so little.</p><h2 id="inside-a-package" tabindex="-1">Inside a Package <a class="header-anchor" href="#inside-a-package" aria-label="Permalink to &quot;Inside a Package&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What</th><th>Where</th></tr></thead><tbody><tr><td>Service provider</td><td><code>packages/Webkul/&lt;Name&gt;/src/Providers/&lt;Name&gt;ServiceProvider.php</code></td></tr><tr><td>Concord module provider</td><td><code>packages/Webkul/&lt;Name&gt;/src/Providers/ModuleServiceProvider.php</code></td></tr><tr><td>Contracts, models and proxies</td><td><code>src/Contracts/</code>, <code>src/Models/</code></td></tr><tr><td>Repositories</td><td><code>src/Repositories/</code></td></tr><tr><td>Migrations, seeders and factories</td><td><code>src/Database/</code></td></tr><tr><td>Routes, controllers, middleware and form requests</td><td><code>src/Routes/</code> (in Paypal and SocialLogin, <code>src/Http/routes.php</code>), <code>src/Http/Controllers/</code>, <code>src/Http/Middleware/</code>, <code>src/Http/Requests/</code></td></tr><tr><td>Event listeners</td><td><code>src/Listeners/</code>, usually mapped in <code>src/Providers/EventServiceProvider.php</code></td></tr><tr><td>Jobs and Artisan commands</td><td><code>src/Jobs/</code>, <code>src/Console/Commands/</code></td></tr><tr><td>Admin listings</td><td><code>src/DataGrids/</code></td></tr><tr><td>Config merged into the application</td><td><code>src/Config/</code></td></tr><tr><td>Blade views</td><td><code>src/Resources/views/</code>, loaded under a namespace such as <code>shop::</code> or <code>admin::</code></td></tr><tr><td>Translations</td><td><code>src/Resources/lang/&lt;locale&gt;/app.php</code>, in all 22 locales</td></tr><tr><td>Front-end sources</td><td><code>src/Resources/assets/</code>, in <code>Admin</code>, <code>Shop</code> and <code>Installer</code></td></tr><tr><td>Pest tests</td><td><code>tests/</code> at the package root, registered as a suite in <code>phpunit.xml</code></td></tr><tr><td>Playwright end-to-end tests</td><td><code>tests/e2e-pw/</code> in <code>Admin</code>, <code>Shop</code> and <code>Installer</code></td></tr></tbody></table><p>Most packages carry only some of these directories; only <code>Providers/</code> is in every one.</p><h2 id="how-a-package-is-wired-in" tabindex="-1">How a Package Is Wired In <a class="header-anchor" href="#how-a-package-is-wired-in" aria-label="Permalink to &quot;How a Package Is Wired In&quot;">​</a></h2><p>A package is loaded because three files name it:</p><ol><li><code>composer.json</code> maps <code>Webkul\\&lt;Name&gt;\\</code> to <code>packages/Webkul/&lt;Name&gt;/src</code> under <code>autoload.psr-4</code>.</li><li><code>bootstrap/providers.php</code> lists the package&#39;s service provider, which loads its routes, views, translations and migrations and merges its config.</li><li><code>config/concord.php</code> lists its <code>ModuleServiceProvider</code>, which registers the package&#39;s models with Concord. A new package needs one only when it has models. In core, 35 packages are listed, 10 of them with an empty model list.</li></ol><p><code>php artisan concord:modules</code> and <code>php artisan concord:models</code> show what Concord has loaded. <a href="./../package-development/getting-started.html">Package Development</a> walks through creating and registering your own package.</p><h2 id="extension-points-at-a-glance" tabindex="-1">Extension Points at a Glance <a class="header-anchor" href="#extension-points-at-a-glance" aria-label="Permalink to &quot;Extension Points at a Glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You want to</th><th>Read</th></tr></thead><tbody><tr><td>Add a feature with its own tables, admin pages and routes</td><td><a href="./../package-development/getting-started.html">Package Development</a></td></tr><tr><td>Add an admin listing</td><td><a href="./../package-development/datagrid.html">DataGrid</a></td></tr><tr><td>Change how the storefront or admin looks</td><td><a href="./../theme-development/getting-started.html">Theme Development</a></td></tr><tr><td>Add a carrier, a gateway or a product type</td><td><a href="./../shipping-method-development/getting-started.html">Shipping</a>, <a href="./../payment-method-development/getting-started.html">payment</a>, <a href="./../product-type-development/getting-started.html">product type</a> development</td></tr><tr><td>React to something the core does</td><td><a href="./../advanced/event-listeners.html">Event Listeners</a></td></tr><tr><td>Add markup to a core page without overriding its view</td><td><a href="./../advanced/view-render-events.html">View Render Events</a></td></tr><tr><td>Replace or extend a core model</td><td><a href="./../package-development/models.html#extending-a-core-model">Extending a Core Model</a></td></tr><tr><td>Change what a core controller, repository, DataGrid or listener does</td><td>Bind a subclass in the container: <a href="./../package-development/controllers.html#things-to-watch">Controllers</a>, <a href="./../package-development/repositories.html#things-to-watch">Repositories</a>, <a href="./../package-development/datagrid.html#extending-a-datagrid-you-do-not-own">DataGrid</a>, <a href="./../advanced/event-listeners.html#things-to-watch">Event Listeners</a></td></tr><tr><td>Change the class behind a core payment method, carrier, product type or importer</td><td>Point its <code>class</code> or <code>importer</code> key at your subclass from <code>boot()</code>: <a href="./../shipping-method-development/understanding-carrier-configuration.html#how-bagisto-uses-the-configuration">Understanding Carrier Configuration</a>, <a href="./../payment-method-development/understanding-payment-configuration.html#things-to-watch">Understanding Payment Configuration</a>, <a href="./../product-type-development/understanding-product-type-configuration.html#overriding-a-core-type">Understanding Product Type Configuration</a>, <a href="./../advanced/understanding-data-transfer.html#step-2-register-the-importer">Understanding Data Transfer</a></td></tr><tr><td>Talk to the store from outside</td><td><a href="./../api/introduction.html">REST and GraphQL APIs</a>, <a href="./../ai/webmcp.html">WebMCP</a></td></tr></tbody></table><p>Each of these works without editing <code>packages/Webkul/</code> or <code>vendor/</code>. Changes made there are overwritten when you update Bagisto.</p><h2 id="next-step" tabindex="-1">Next Step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next Step&quot;">​</a></h2><p><a href="./../package-development/getting-started.html">Package Development</a> builds your first package. For more of the map first, read <a href="./backend.html">Backend Architecture</a> (the request flow and all 42 packages) and <a href="./frontend.html">Frontend Architecture</a> (Blade, Vue.js and Vite).</p>`,21)]))}const m=t(d,[["render",n]]);export{g as __pageData,m as default};
